/**
 * .gitignore generator and tester. Templates are condensed from the
 * community-maintained github/gitignore repository (CC0-1.0), keeping the
 * patterns that matter for each stack and dropping rarely used tool output.
 * The matcher follows the rules in the git documentation (gitignore(5)):
 * blank lines and # comments are ignored, ! negates, a trailing / matches
 * directories only, a slash at the start or middle anchors the pattern to the
 * .gitignore's directory, * and ? do not cross /, ** matches across
 * directories, the last matching pattern wins, and a file cannot be
 * re-included if a parent directory is excluded.
 */

import { msg } from '../../msg';

export type TemplateGroup = 'Language' | 'Framework' | 'Tool' | 'IDE' | 'OS';

export type GitignoreTemplate = { id: string; name: string; group: TemplateGroup; keywords?: string; lines: string[] };

const T = (id: string, name: string, group: TemplateGroup, body: string, keywords?: string): GitignoreTemplate => ({
  id,
  name,
  group,
  keywords,
  lines: body.trim().split('\n').map((l) => l.trimEnd()),
});

