export function getTemplate(id: string): GitignoreTemplate | undefined {
  return GITIGNORE_TEMPLATES.find((t) => t.id === id);
}

export function findTemplates(query: string): GitignoreTemplate[] {
  const q = query.trim().toLowerCase();
  if (!q) return GITIGNORE_TEMPLATES;
  return GITIGNORE_TEMPLATES.filter((t) => `${t.id} ${t.name} ${t.keywords ?? ''} ${t.group}`.toLowerCase().includes(q));
}

/**
 * Combine templates into one file with a header per section. Lines already
 * present in an earlier section are dropped (comments and blank lines are
 * kept), so the order of negations within each template is preserved.
 */
export function buildGitignore(ids: string[], extra = '', opts: { header?: boolean } = {}): { content: string; unknown: string[]; duplicatesRemoved: number } {
  const unknown: string[] = [];
  const seen = new Set<string>();
  let duplicatesRemoved = 0;
  const parts: string[] = [];
  if (opts.header !== false) parts.push('# Generated with the RedBison .gitignore Generator (templates based on github/gitignore, CC0)');
  const uniq = [...new Set(ids.map((s) => s.trim().toLowerCase()).filter(Boolean))];
  for (const id of uniq) {
    const t = getTemplate(id) ?? GITIGNORE_TEMPLATES.find((x) => x.name.toLowerCase() === id);
    if (!t) {
      unknown.push(id);
      continue;
    }
    // Work in blank-line separated blocks so a comment header disappears with its patterns.
    const blocks: string[][] = [[]];
    for (const line of t.lines) {
      if (line.trim() === '') blocks.push([]);
      else blocks[blocks.length - 1].push(line);
    }
    const kept: string[] = [];
    for (const block of blocks) {
      const isPattern = (l: string) => !l.trim().startsWith('#');
      const hadPatterns = block.some(isPattern);
      const out: string[] = [];
      for (const line of block) {
        if (isPattern(line)) {
          if (seen.has(line.trim())) {
            duplicatesRemoved++;
            continue;
          }
          seen.add(line.trim());
        }
        out.push(line);
      }
      if (out.length && (!hadPatterns || out.some(isPattern))) kept.push(out.join('\n'));
    }
    const cleaned = kept.join('\n\n').trim();
    if (cleaned) parts.push(`### ${t.name} ###\n${cleaned}`);
  }
  const extraLines = extra.split(/\r?\n/).map((l) => l.trimEnd()).filter((l) => l.trim());
  if (extraLines.length) parts.push(`### Custom ###\n${extraLines.join('\n')}`);
  return { content: parts.join('\n\n') + '\n', unknown, duplicatesRemoved };
}

// ---------- Matcher ----------

type Rule = { negate: boolean; dirOnly: boolean; re: RegExp; source: string; line: number };

/** Convert one gitignore pattern to a regex over a slash-separated path relative to the repo root. */
function compile(pattern: string, line: number): Rule | null {
  let p = pattern.replace(/\r$/, '');
  if (!p.trim() || p.startsWith('#')) return null;
  // Trailing spaces are ignored unless escaped with a backslash.
  p = p.replace(/(?<!\\)\s+$/, '');
  let negate = false;
  if (p.startsWith('!')) {
    negate = true;
    p = p.slice(1);
  } else if (p.startsWith('\\!') || p.startsWith('\\#')) p = p.slice(1);
  let dirOnly = false;
  if (p.endsWith('/')) {
    dirOnly = true;
    p = p.slice(0, -1);
  }
  const anchored = p.includes('/');
  if (p.startsWith('/')) p = p.slice(1);
  let re = '';
  for (let i = 0; i < p.length; i++) {
    const c = p[i];
    if (c === '*') {
      if (p[i + 1] === '*') {
        const prevSlash = i === 0 || p[i - 1] === '/';
        const nextSlash = p[i + 2] === '/' || i + 2 === p.length;
        if (prevSlash && nextSlash) {
          if (i + 2 === p.length) re += '.*';
          else {
            re += '(?:.*/)?';
            i += 2; // skip "**/"
            continue;
          }
          i++;
          continue;
        }
      }
      re += '[^/]*';
      while (p[i + 1] === '*') i++;
    } else if (c === '?') re += '[^/]';
    else if (c === '[') {
      const end = p.indexOf(']', i + 2);
      if (end < 0) re += '\\[';
      else {
        let cls = p.slice(i + 1, end).replace(/\\/g, '\\\\');
        if (cls.startsWith('!')) cls = '^' + cls.slice(1);
        re += `[${cls}]`;
        i = end;
      }
    } else if (c === '\\' && i + 1 < p.length) {
      re += p[i + 1].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      i++;
    } else re += c.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
  }
  const full = anchored ? `^${re}$` : `^(?:.*/)?${re}$`;
  return { negate, dirOnly, re: new RegExp(full), source: pattern, line };
}

export function compileGitignore(content: string): Rule[] {
  return content
    .split('\n')
    .map((l, i) => compile(l, i + 1))
    .filter((r): r is Rule => r !== null);
}

export type MatchResult = { ignored: boolean; rule?: { pattern: string; line: number; negate: boolean }; via?: string };

function matchOne(rules: Rule[], path: string, isDir: boolean): Rule | undefined {
  let hit: Rule | undefined;
  for (const r of rules) {
    if (r.dirOnly && !isDir) continue;
    if (r.re.test(path)) hit = r;
  }
  return hit;
}

/**
 * Is `path` ignored? A path ending in "/" is treated as a directory. Parent
 * directories are checked first, because git does not descend into an
 * excluded directory and a "!" rule cannot bring its files back.
 */
export function checkIgnored(content: string, rawPath: string): MatchResult {
  const rules = compileGitignore(content);
  let path = rawPath.trim().replace(/\\/g, '/').replace(/^\.\//, '').replace(/^\/+/, '');
  const isDir = path.endsWith('/');
  path = path.replace(/\/+$/, '');
  if (!path) return { ignored: false };
  const segs = path.split('/');
  for (let k = 1; k < segs.length; k++) {
    const parent = segs.slice(0, k).join('/');
    const r = matchOne(rules, parent, true);
    if (r && !r.negate) return { ignored: true, rule: { pattern: r.source, line: r.line, negate: false }, via: parent + '/' };
  }
  const r = matchOne(rules, path, isDir);
  if (!r) return { ignored: false };
  return { ignored: !r.negate, rule: { pattern: r.source, line: r.line, negate: r.negate } };
}
